package com.companages.controller; import com.companages.dto.*; import com.companages.dto.InvitationDtos.*; import com.companages.entity.InvitationStatus; import com.companages.service.InvitationService; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class InvitationController {private final InvitationService service;public InvitationController(InvitationService s){service=s;}@PostMapping("/organizations/{organizationId}/invitations")ResponseEntity<Response> send(@PathVariable Long organizationId,@Valid@RequestBody InviteRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.send(organizationId,r));}@GetMapping("/organizations/{organizationId}/invitations")PageResponse<Response> list(@PathVariable Long organizationId,@RequestParam(required=false)String search,@RequestParam(required=false)InvitationStatus status,@PageableDefault(sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return service.list(organizationId,search,status,p);}@PostMapping("/organizations/{organizationId}/invitations/{id}/resend")Response resend(@PathVariable Long organizationId,@PathVariable Long id){return service.resend(organizationId,id);}@DeleteMapping("/organizations/{organizationId}/invitations/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void cancel(@PathVariable Long organizationId,@PathVariable Long id){service.cancel(organizationId,id);}@GetMapping("/invitations/validate/{token}")Response validate(@PathVariable String token){return service.validate(token);}@PostMapping("/invitations/accept")Response accept(@Valid@RequestBody AcceptRequest r){return service.accept(r);}}
